function loadEvents(){try{const x=JSON.parse(localStorage.getItem(KEY));return Array.isArray(x)&&x.length?x:[structuredClone(seed)]}catch{return[structuredClone(seed)]}}
function loadUsers(){try{const x=JSON.parse(localStorage.getItem(USERS_KEY));return Array.isArray(x)?x:[]}catch{return[]}}
function saveUsers(){localStorage.setItem(USERS_KEY,JSON.stringify(users))}
function save(){localStorage.setItem(KEY,JSON.stringify(events));localStorage.setItem(KEY+':current',currentId)}
function event(){return events.find(x=>x.id===currentId)||events[0]}
function canEdit(){return authUser&&['admin','editor'].includes(authUser.role)}
function audit(action,detail){if(!authUser||!event())return;const e=event();e.logs=e.logs||[];e.logs.unshift({at:new Date().toISOString(),user:authUser.name,email:authUser.email,action,detail});save()}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function statusKey(s=''){s=String(s).toLowerCase();if(s.includes('done')||s.includes('confirm'))return'confirm';if(s.includes('run')||s.includes('process')||s.includes('scheduled')||s.includes('ongoing'))return'process';if(s.includes('cancel'))return'cancel';if(s.includes('respond')||s.includes('deliver'))return'response';return'open'}
function pill(s){let k=statusKey(s);return `<span class="pill ${k==='confirm'?'done':k==='process'?'running':k==='cancel'?'cancel':k==='response'?'not-delivered':''}">${esc(s||'To do')}</span>`}
function dateShort(s){if(!s)return'—';let d=new Date(s+'T12:00:00');return isNaN(d)?esc(s):d.toLocaleDateString('id-ID',{day:'numeric',month:'short'})}
function dateRange(start,end){if(!start)return'Tanggal belum diatur';const a=new Date(start+'T12:00:00'),b=new Date((end||start)+'T12:00:00');if(isNaN(a))return'Tanggal belum diatur';if(isNaN(b)||start===(end||start))return a.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});const sameYear=a.getFullYear()===b.getFullYear(),sameMonth=sameYear&&a.getMonth()===b.getMonth();if(sameMonth)return `${a.getDate()}–${b.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}`;if(sameYear)return `${a.toLocaleDateString('id-ID',{day:'numeric',month:'short'})} – ${b.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}`;return `${a.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})} – ${b.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}`}
function fmtNum(n){return new Intl.NumberFormat('id-ID').format(Number(n)||0)}
function fmtCurrency(n){return'Rp '+fmtNum(Math.max(0,Number(n)||0))}
function safeDriveLink(value){try{const u=new URL(String(value||''));return u.protocol==='https:'&&['drive.google.com','docs.google.com'].includes(u.hostname)?u.href:''}catch{return''}}
function driveDownloadLink(value){const safe=safeDriveLink(value);if(!safe)return'';const u=new URL(safe),id=u.pathname.match(/\/d\/([^/]+)/)?.[1]||u.searchParams.get('id');if(!id)return safe;if(u.hostname==='docs.google.com')return `${u.origin}${u.pathname.split('/d/')[0]}/d/${encodeURIComponent(id)}/export?format=pdf`;return `https://drive.google.com/uc?export=download&id=${encodeURIComponent(id)}`}
function renderEventMap(e){const map=e.eventMap,content=document.getElementById('eventMapContent'),remove=document.getElementById('removeEventMap');if(!map){content.innerHTML='<p>Belum ada peta. Upload gambar ringan atau PDF layout venue.</p>';remove.classList.add('hidden');return}const name=esc(map.name||'Event map'),link=map.data||'';remove.classList.toggle('hidden',!canEdit());content.innerHTML=map.type==='application/pdf'?`<div class="event-map-file"><span class="map-file-icon">PDF</span><div><b>${name}</b><small>${(Number(map.size)||0)/1048576<1?`${Math.max(1,Math.round((Number(map.size)||0)/1024))} KB`:`${((Number(map.size)||0)/1048576).toFixed(1)} MB`}</small></div><a class="btn btn-outline map-download" href="${link}" download="${name}" target="_blank" rel="noopener">↓ Download map</a></div>`:`<div class="event-map-preview"><a href="${link}" target="_blank" rel="noopener"><img src="${link}" alt="${name}"></a><div class="event-map-file"><b>${name}</b><a class="btn btn-outline map-download" href="${link}" download="${name}">↓ Download map</a></div></div>`}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('File tidak dapat dibaca.'));reader.readAsDataURL(file)})}
async function compressMapImage(file){if(!('createImageBitmap'in window))return fileToDataUrl(file);const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.78));if(!blob)throw new Error('Gambar tidak dapat diproses.');if(blob.size>950000){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.58))}if(!blob||blob.size>1400000)throw new Error('Peta gambar terlalu besar setelah dikompres. Coba gambar yang lebih kecil.');return fileToDataUrl(new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp'}))}
async function storeEventMap(file){if(!canEdit())return toast('Akun ini hanya memiliki akses lihat.');if(!file)return;if(file.size>2*1024*1024)return toast('Ukuran file maksimal 2 MB.');if(file.type!=='application/pdf'&&!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Gunakan file PDF, PNG, JPG, atau WebP.');try{const previous=event().eventMap,data=file.type==='application/pdf'?await fileToDataUrl(file):await compressMapImage(file);event().eventMap={name:file.type==='application/pdf'?file.name:file.name.replace(/\.[^.]+$/,'')+'.webp',type:file.type==='application/pdf'?'application/pdf':'image/webp',data,size:file.type==='application/pdf'?file.size:Math.round(data.length*0.75)};try{save()}catch(err){event().eventMap=previous;throw err}audit('Event map updated',`${event().eventMap.name} · ${(event().eventMap.size/1024).toFixed(0)} KB`);render();toast('Event map berhasil disimpan')}catch(err){toast(err.message||'Event map tidak dapat disimpan.')}finally{document.getElementById('eventMapFile').value=''}}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function passwordHash(password,salt){if(!crypto?.subtle)throw new Error('Secure password storage membutuhkan browser modern melalui HTTPS atau localhost.');const enc=new TextEncoder();return crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']).then(k=>crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:160000,hash:'SHA-256'},k,256)).then(bits=>btoa(String.fromCharCode(...new Uint8Array(bits))))}
function showAuth(){const gate=document.getElementById('authGate'),form=document.getElementById('authForm'),fields=document.getElementById('authFields');gate.classList.remove('hidden');if(users.length===0){form.dataset.mode='setup';document.getElementById('authTitle').textContent='Buat akun admin';document.getElementById('authMessage').textContent='Akun pertama akan menjadi admin untuk workspace HIVE ini.';document.getElementById('authSubmit').textContent='Buat admin';fields.innerHTML=field('NAMA LENGKAP','name')+field('EMAIL','email','','email')+field('PASSWORD · MIN. 8 KARAKTER','password','','password')}else{form.dataset.mode='login';document.getElementById('authTitle').textContent='Masuk ke workspace';document.getElementById('authMessage').textContent='Masuk untuk mengelola event dan melihat activity log.';document.getElementById('authSubmit').textContent='Masuk';fields.innerHTML=field('EMAIL','email','','email')+field('PASSWORD','password','','password')}document.querySelector('#authFields input')?.focus()}
async function initializeAuth(){users=loadUsers();let session=null;try{session=JSON.parse(localStorage.getItem(SESSION_KEY))}catch{}authUser=users.find(u=>u.id===session?.userId&&u.active);if(authUser){document.getElementById('authGate').classList.add('hidden');audit('Login','Masuk ke workspace');render()}else showAuth()}
document.getElementById('authForm').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,data=new FormData(form),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||'');try{if(!crypto?.subtle)throw new Error('Browser membutuhkan HTTPS atau localhost untuk menyimpan password dengan aman.');if(form.dataset.mode==='setup'){const name=String(data.get('name')||'').trim();if(!name||!email||password.length<8)throw new Error('Isi nama, email, dan password minimal 8 karakter.');const salt=crypto.getRandomValues(new Uint8Array(16));const saltText=btoa(String.fromCharCode(...salt));const hash=await passwordHash(password,saltText);const user={id:'user-'+Date.now(),name,email,role:'admin',active:true,salt:saltText,passwordHash:hash,createdAt:new Date().toISOString()};users=[user];saveUsers();authUser=user;localStorage.setItem(SESSION_KEY,JSON.stringify({userId:user.id}));document.getElementById('authGate').classList.add('hidden');audit('Workspace created','Akun admin pertama dibuat');render();toast('Akun admin berhasil dibuat')}else{const user=users.find(u=>u.email===email&&u.active);if(!user)throw new Error('Email belum terdaftar atau akun dinonaktifkan.');const hash=await passwordHash(password,user.salt);if(hash!==user.passwordHash)throw new Error('Email atau password tidak sesuai.');authUser=user;localStorage.setItem(SESSION_KEY,JSON.stringify({userId:user.id}));document.getElementById('authGate').classList.add('hidden');audit('Login','Masuk ke workspace');render();toast(`Selamat datang, ${user.name}`)}}catch(err){toast(err.message||'Tidak dapat masuk. Coba lagi.')}});
document.getElementById('logoutButton').addEventListener('click',()=>{if(authUser)audit('Logout','Keluar dari workspace');localStorage.removeItem(SESSION_KEY);authUser=null;showAuth()});
function applyRolePermissions(){document.getElementById('profileName').textContent=authUser?.name||'Signed out';document.getElementById('profileRole').textContent=authUser?.role||'User session';document.getElementById('profileInitial').textContent=(authUser?.name||'?').slice(0,2).toUpperCase();const admin=authUser?.role==='admin';document.getElementById('addUserButton').classList.toggle('hidden',!admin);document.querySelectorAll('[data-add],#editEvent,#ticketingEdit,#ticketingStart').forEach(el=>el.classList.toggle('hidden',!canEdit()));document.getElementById('newEventTop').classList.toggle('hidden',!admin);document.querySelectorAll('[data-task],[data-partner],[data-media],[data-equipment]').forEach(el=>el.disabled=!canEdit());document.getElementById('eventMapUploadButton').classList.toggle('hidden',!canEdit());document.getElementById('removeEventMap').classList.toggle('hidden',!canEdit()||!event()?.eventMap);}
function renderUsersAudit(){const logs=event()?.logs||[],search=(document.getElementById('auditSearch')?.value||'').toLowerCase();document.getElementById('userCount').textContent=users.length;document.getElementById('auditCount').textContent=logs.length;document.getElementById('currentUserLabel').textContent=authUser?.name||'—';document.getElementById('usersTable').innerHTML=users.map((u,i)=>`<tr><td><span class="item-name">${esc(u.name)}</span></td><td>${esc(u.email)}</td><td><select data-user-role="${i}" ${authUser?.role!=='admin'||u.id===authUser?.id?'disabled':''}>${['admin','editor','viewer'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></td><td>${u.active?'Aktif':'Nonaktif'}</td><td><button class="text-button" data-user-active="${i}" ${authUser?.role!=='admin'||u.id===authUser?.id?'disabled':''}>${u.active?'Nonaktifkan':'Aktifkan'}</button></td></tr>`).join('');document.getElementById('auditTable').innerHTML=logs.filter(l=>`${l.user} ${l.action} ${l.detail}`.toLowerCase().includes(search)).map(l=>`<tr><td>${new Date(l.at).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}</td><td><span class="item-name">${esc(l.user)}</span><span class="cell-sub">${esc(l.email)}</span></td><td>${esc(l.action)}</td><td>${esc(l.detail||'—')}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada aktivitas yang cocok.</td></tr>'}
function setPage(name){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+name));document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===name));if(location.hash!=='#'+name)history.replaceState(null,'','#'+name);document.getElementById('sidebar').classList.remove('open');window.scrollTo(0,0)}
function renderMetricIcons(){const icons={megaphone:'<path d="M3 11v2h4l11 5V6L7 11H3Z"/><path d="M7 13l2 6h3l-2-7M20 10l2-1v6l-2-1"/>',clock:'<circle cx="12" cy="12" r="8.5"/><path d="M12 7v5l3.5 2"/>',receipt:'<path d="M5 4h14v16l-3-2-4 2-4-2-3 2V4Z"/><path d="M8 9h8M8 13h5"/>',layout:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M4 9h16M9 9v11"/>',checklist:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="m7 9 1.5 1.5L11 8M13 9h4M7 15l1.5 1.5L11 14M13 15h4"/>',partners:'<path d="m3.5 12 4-4 4.2.4 1.4-1.2 3 .7 4.4 4.1-3.7 4-2.3-1.7-2.2 1.7-2.3-1.8-1.8 1.4L3.5 12Z"/><path d="m8 8 3 2.6c.8.7 1.9.6 2.6-.1l1.1-1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3.5 19c.4-3.1 2.2-5 5.5-5s5.1 1.9 5.5 5M16 5.5a3 3 0 0 1 0 5.8M17 14c2.1.6 3.3 2.2 3.6 5"/>',box:'<path d="m4 8 8-4 8 4-8 4-8-4Z"/><path d="M4 8v9l8 4 8-4V8M12 12v9"/>',check:'<circle cx="12" cy="12" r="8.5"/><path d="m8 12 2.6 2.6L16.5 9"/>',truck:'<path d="M3 6h11v11H3zM14 10h4l3 3v4h-7"/><circle cx="7" cy="19" r="1.5"/><circle cx="18" cy="19" r="1.5"/>'};document.querySelectorAll('.metric-icon').forEach(el=>{const label=el.closest('.metric-card')?.querySelector('.metric-top>span')?.textContent?.trim().toUpperCase()||'';const key=label.includes('MEDIA BUZZER')?'megaphone':label.includes('TERJADWAL')||label.includes('DELIVERY')?'clock':label.includes('RATE')?'receipt':label.includes('CONTENT TRACKER')?'layout':label.includes('TASK')?'checklist':label.includes('SPONSOR')||label.includes('PARTNER')?'partners':label.includes('COMMUNITY')||label.includes('VOLUNTEER')||label.includes('KOL')?'users':label.includes('ITEM TERCATAT')?'box':label.includes('CHECKED')||label.includes('CONFIRMED')?'check':'layout';el.innerHTML=`<svg class="metric-svg" viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>`})}
