function reportHeader(e,title){return `<header class="print-report-head"><div><div class="print-kicker">HIVE EVENT DASHBOARD · ${esc(title)}</div><h1>${esc(e.name||'Event')}</h1><p>${esc(e.venue||'Venue belum diatur')} · ${esc(dateRange(e.startDate||e.date,e.endDate||e.date||e.startDate))}${e.format?` · ${esc(e.format)}`:''}</p></div><span class="print-date">Dibuat ${new Date().toLocaleDateString('id-ID',{dateStyle:'medium'})}</span></header>`}
function printReport(){const e=event();if(!e)return;const tasks=e.tasks||[],partners=e.partners||[],communities=e.communities||[],kol=e.kol||[],media=e.media||[],equipment=e.equipment||[],done=tasks.filter(t=>statusKey(t[4])==='confirm').length,readiness=tasks.length?Math.round(done/tasks.length*100):0,cash=partners.reduce((s,p)=>s+(Number(p[4])||0),0),product=partners.reduce((s,p)=>s+(Number(p[5])||0),0),confirmedCommunity=communities.filter(c=>statusKey(c[2])==='confirm').length,scheduled=media.filter(m=>statusKey(m[1])==='process').length,checked=equipment.filter(x=>x[4]).length,vol=e.volunteers||{target:0,filled:0,roles:[]},ticketCapacity=Number(e.ticketCapacity)||0,ticketSales=Number(e.ticketSales)||0;
 const cats=[...new Set(tasks.map(t=>t[1]||'Uncategorized'))].map(cat=>{const group=tasks.filter(t=>(t[1]||'Uncategorized')===cat),finished=group.filter(t=>statusKey(t[4])==='confirm').length,pct=group.length?Math.round(finished/group.length*100):0;return `<tr><td>${esc(cat)}</td><td>${group.length}</td><td>${finished}</td><td><div class="print-bar"><i style="width:${pct}%"></i></div></td><td>${pct}%</td></tr>`}).join('')||'<tr><td colspan="5">Belum ada task</td></tr>';
 const attention=tasks.filter(t=>statusKey(t[4])!=='confirm').slice(0,8),recent=(e.logs||[]).slice(0,6),card=(label,value,note)=>`<article class="print-kpi"><small>${label}</small><strong>${value}</strong><span>${note}</span></article>`;
 document.getElementById('printReport').innerHTML=`${reportHeader(e,'EVENT SUMMARY')}<section class="print-kpis">${card('EVENT READINESS',readiness+'%',`${done} / ${tasks.length} task selesai`)}${card('SPONSOR VALUE',fmtCurrency(cash+product),`Cash ${fmtCurrency(cash)} · Product ${fmtCurrency(product)}`)}${card('MEDIA PLACEMENT',media.length,`${scheduled} terjadwal · ${fmtCurrency(media.reduce((s,m)=>s+(Number(m[2])||0),0))} total rate`)}${card('TEAM & VOLUNTEERS',fmtNum(vol.filled||0),`${fmtNum(vol.target||0)} target role · ${(e.team||[]).length} team role`)}</section><div class="print-columns"><section class="print-section"><h2>Task progress by category</h2><table><thead><tr><th>Category</th><th>Tasks</th><th>Done</th><th>Progress</th><th>%</th></tr></thead><tbody>${cats}</tbody></table><div class="print-callout"><b>${tasks.length-done} task</b> masih perlu perhatian · <b>${partners.filter(p=>statusKey(p[2])!=='confirm').length} sponsor</b> perlu follow-up</div><h2>Priority tasks</h2><table><thead><tr><th>Task</th><th>Category</th><th>Deadline</th><th>Status</th></tr></thead><tbody>${attention.map(t=>`<tr><td>${esc(t[0])}</td><td>${esc(t[1]||'—')}</td><td>${esc(dateShort(t[2]))}</td><td>${esc(t[4]||'—')}</td></tr>`).join('')||'<tr><td colspan="4">Semua task selesai</td></tr>'}</tbody></table></section><section class="print-section"><h2>Partners & audience</h2><div class="print-facts"><span>Sponsors recorded</span><b>${partners.length}</b><span>Confirmed sponsors</span><b>${partners.filter(p=>statusKey(p[2])==='confirm').length}</b><span>Cash support</span><b>${fmtCurrency(cash)}</b><span>Product support value</span><b>${fmtCurrency(product)}</b><span>Communities confirmed</span><b>${confirmedCommunity} / ${communities.length}</b><span>KOL & athletes</span><b>${kol.length}</b></div><h2>Event day readiness</h2><div class="print-facts"><span>Equipment checked</span><b>${checked} / ${equipment.length}</b><span>Volunteer roster</span><b>${fmtNum(vol.filled||0)} / ${fmtNum(vol.target||0)}</b>${ticketCapacity?`<span>Tickets sold</span><b>${fmtNum(ticketSales)} / ${fmtNum(ticketCapacity)}</b><span>Remaining capacity</span><b>${fmtNum(Math.max(0,ticketCapacity-ticketSales))}</b><span>Ticket sales value</span><b>${fmtCurrency(ticketSales*(Number(e.ticketPrice)||0))}</b>`:''}</div><h2>Recent activity</h2><table><thead><tr><th>Time</th><th>Updated by</th><th>Activity</th></tr></thead><tbody>${recent.map(l=>`<tr><td>${new Date(l.at).toLocaleString('id-ID',{dateStyle:'short',timeStyle:'short'})}</td><td>${esc(l.user||'—')}</td><td>${esc(l.action||'')} · ${esc(l.detail||'')}</td></tr>`).join('')||'<tr><td colspan="3">Belum ada activity log</td></tr>'}</tbody></table></section></div><footer class="print-footer">HIVE EVENT DASHBOARD · Internal event summary</footer>`;
 document.body.classList.remove('print-checklist-mode');document.body.classList.add('print-report-mode');window.print()}
