document.getElementById('modalForm').addEventListener('submit',async ev=>{if(ev.submitter?.value!=='save')return;ev.preventDefault();const f=new FormData(ev.currentTarget),form=ev.currentTarget,kind=form.dataset.kind,editing=form.dataset.edit==='yes';if(kind==='ticket')return;if(kind==='user'){if(authUser?.role!=='admin')return toast('Hanya admin yang dapat mengelola user.');const name=String(f.get('name')||'').trim(),email=String(f.get('email')||'').trim().toLowerCase(),password=String(f.get('password')||'');if(!name||!email||password.length<8)return toast('Isi nama, email, dan password minimal 8 karakter.');if(users.some(u=>u.email===email))return toast('Email tersebut sudah terdaftar.');try{const salt=btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(16))));const hash=await passwordHash(password,salt);users.push({id:'user-'+Date.now(),name,email,role:f.get('role'),active:true,salt,passwordHash:hash,createdAt:new Date().toISOString()});saveUsers();audit('User invited',`${email} · role ${f.get('role')}`);toast('User berhasil ditambahkan')}catch(err){return toast(err.message||'User tidak dapat dibuat.')}}else{if(!canEdit())return toast('Akun ini hanya memiliki akses lihat.');const e=event();if(kind==='event'){if(f.get('startDate')&&f.get('endDate')&&f.get('endDate')<f.get('startDate'))return toast('Tanggal selesai tidak boleh sebelum tanggal mulai.');if(editing){const old=e.name;Object.assign(e,{name:f.get('name')||'Event',venue:f.get('venue')||'',startDate:f.get('startDate')||'',endDate:f.get('endDate')||f.get('startDate')||'',format:f.get('format')||''});delete e.date;delete e.distance;audit('Event updated',`${old} · informasi event diperbarui`)}else{const fresh=f.get('copy')?structuredClone(event()):emptyEvent();fresh.id='event-'+Date.now();fresh.name=f.get('name')||'New Event';fresh.venue=f.get('venue')||'';fresh.startDate=f.get('startDate')||'';fresh.endDate=f.get('endDate')||f.get('startDate')||'';fresh.format=f.get('format')||'';delete fresh.eventMap;delete fresh.date;delete fresh.distance;fresh.logs=[];if(f.get('copy')){(fresh.tasks||[]).forEach(x=>x[4]='—');(fresh.partners||[]).forEach(x=>x[2]='—');(fresh.media||[]).forEach(x=>x[1]='—');(fresh.communities||[]).forEach(x=>{x[2]='—';x[3]='—'});(fresh.kol||[]).forEach(x=>x[4]='—');(fresh.equipment||[]).forEach(x=>x[4]=false);if(fresh.volunteers)fresh.volunteers.filled=0;fresh.ticketSales=0;}else fresh.volunteers={...structuredClone(seed.volunteers),filled:0};events.unshift(fresh);currentId=fresh.id;audit('Event created',`${fresh.name} · ${fresh.venue||'lokasi belum diatur'}`);toast('Event baru siap digunakan')} }else if(kind==='mediaDetails'){const idx=Number(form.dataset.mediaIndex),item=e.media[idx],old=`rate ${item[2]||'—'}, post ${item[3]||'—'}`;item[0]=f.get('name');item[1]=f.get('status');item[2]=f.get('rate');item[3]=f.get('schedule');item[4]=f.get('link');item[5]=f.get('notes');audit('Media details updated',`${item[0]} · ${old} → rate ${item[2]||'—'}, post ${item[3]||'—'}`);toast('Detail media diperbarui')}else{if(kind==='task')e.tasks.unshift([f.get('name'),f.get('category'),f.get('deadline'),f.get('note'),f.get('status')]);if(kind==='partner'){const sponsorPdf=String(f.get('sponsorPdf')||'').trim();if(sponsorPdf&&!safeDriveLink(sponsorPdf))return toast('Gunakan tautan HTTPS Google Drive atau Google Docs.');const partner=[f.get('name'),f.get('category'),f.get('status'),f.get('note'),Math.max(0,Number(f.get('cash'))||0),Math.max(0,Number(f.get('product'))||0),sponsorPdf];if(editing){const idx=Number(form.dataset.partnerIndex),old=e.partners[idx];e.partners[idx]=partner;audit('Sponsor details updated',`${partner[0]} · cash ${fmtCurrency(old?.[4])} → ${fmtCurrency(partner[4])} · product ${fmtCurrency(old?.[5])} → ${fmtCurrency(partner[5])}`);toast('Detail sponsor diperbarui')}else e.partners.unshift(partner)}if(kind==='media')e.media.unshift([f.get('name'),f.get('status'),f.get('rate'),f.get('schedule'),f.get('link'),f.get('notes')]);if(kind==='kol')e.kol.unshift([f.get('name'),f.get('format'),f.get('pax'),f.get('sow'),f.get('status'),f.get('profile')]);if(kind==='equipment')e.equipment.unshift([f.get('name'),f.get('pic'),f.get('qty'),f.get('delivery'),false]);if(kind==='crew'){const role=String(f.get('newRole')||'').trim()||String(f.get('role')||'').trim(),person=String(f.get('person')||'').trim();if(!role||!person)return toast('Pilih atau isi peran dan nama penanggung jawab.');if(editing){const idx=Number(form.dataset.teamIndex),old=e.team[idx];e.team[idx]=[role,person];audit('Team role updated',`${old?.[0]||'Role'} · ${old?.[1]||'—'} → ${role} · ${person}`);toast('Team berhasil diperbarui')}else e.team.unshift([role,person])}if(!((kind==='partner'||kind==='crew')&&editing))audit('Item added',`${kind} · ${kind==='crew'?`${f.get('newRole')||f.get('role')} · ${f.get('person')}`:f.get('name')||f.get('role')||'new item'}`);if(!((kind==='partner'||kind==='crew')&&editing))toast('Item berhasil ditambahkan')}}save();document.getElementById('modal').close();render()});
function emptyEvent(){return{id:'',name:'New Event',venue:'',startDate:'',endDate:'',format:'',eventMap:null,tasks:[],partners:[],communities:[],kol:[],media:[],equipment:[],volunteers:{target:0,filled:0,roles:[]},team:[],ticketSales:0}}
document.getElementById('ticketingEdit').onclick=()=>ticketModal();document.getElementById('ticketingStart').onclick=()=>ticketModal();document.getElementById('addUserButton').onclick=()=>openModal('user');document.getElementById('auditSearch').addEventListener('input',renderUsersAudit);function ticketModal(){const e=event();document.getElementById('modalKicker').textContent='TICKETING';document.getElementById('modalTitle').textContent='Atur kapasitas tiket';document.getElementById('modalFields').innerHTML=field('KAPASITAS PESERTA','capacity',e.ticketCapacity||'','number')+field('TIKET TERJUAL','sold',e.ticketSales||0,'number')+field('HARGA TIKET (RP)','price',e.ticketPrice||'','number');document.getElementById('modalSubmit').textContent='Simpan kapasitas';document.getElementById('modalForm').dataset.kind='ticket';document.getElementById('modalForm').dataset.edit='no';document.getElementById('modal').showModal()}
const modalSubmit=document.getElementById('modalForm');modalSubmit.addEventListener('submit',ev=>{if(ev.submitter&&ev.submitter.value==='cancel')return});
document.getElementById('exportTasks').onclick=()=>{const rows=[['Task','Category','Deadline','PIC / Notes','Status'],...event().tasks];const csv=rows.map(r=>r.map(x=>'"'+String(x||'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`${event().name.toLowerCase().replaceAll(' ','-')}-tasks.csv`;a.click();URL.revokeObjectURL(a.href)};
document.getElementById('modalForm').addEventListener('submit',ev=>{if(ev.submitter?.value!=='save')return;if(ev.currentTarget.dataset.kind==='ticket'){ev.preventDefault();if(!canEdit())return toast('Akun ini hanya memiliki akses lihat.');const f=new FormData(ev.currentTarget);event().ticketCapacity=f.get('capacity');event().ticketSales=Number(f.get('sold'))||0;event().ticketPrice=f.get('price');audit('Ticketing updated',`${event().ticketSales} tiket terjual dari kapasitas ${event().ticketCapacity}`);save();document.getElementById('modal').close();render();toast('Data ticketing disimpan')}});
initializeAuth();
